from pathlib import Path
import hashlib

source_path = Path('tools/ats_question_triage.py')
immutable_path = Path('tests/test_ats_question_triage.py')
regression_path = Path('tests/test_ats_question_triage_autonomous.py')
expected_hash = '8b4d37223ee08c0add0d5b349875a8e8983cd0d9'

if hashlib.sha256(immutable_path.read_bytes()).hexdigest() != expected_hash:
    raise RuntimeError('Immutable regression baseline differs from sealed contract')

if regression_path.exists():
    raise RuntimeError('Autonomous regression file already exists; refusing overwrite')

original = source_path.read_text(encoding='utf-8')

old = '''    for key, pattern in _CONTACT.items():
        if pattern.fullmatch(question) and (not label or pattern.fullmatch(label)):
            if key in verified_keys:
                return {"status":"verified_candidate","profile_key":key}
            return {"status":"human_review","reason":"unverified_profile_fact"}
'''

new = '''    expected_kinds = {
        "full_name": "text",
        "email": "email",
        "phone": "tel",
        "linkedin": "url",
        "github": "url",
    }
    for key, pattern in _CONTACT.items():
        if pattern.fullmatch(question) and (not label or pattern.fullmatch(label)):
            if kind != "text" and kind != expected_kinds[key]:
                return {"status":"human_review","reason":"mismatched_contact_control"}
            if key in verified_keys:
                return {"status":"verified_candidate","profile_key":key}
            return {"status":"human_review","reason":"unverified_profile_fact"}
'''

if original.count(old) != 1:
    raise RuntimeError('Expected classifier implementation not found exactly once')

regressions = '''import pytest

from tools.ats_question_triage import classify_field, triage_fields


@pytest.mark.parametrize("question,kind,key", [
    ("Full name", "email", "full_name"),
    ("Full name", "tel", "full_name"),
    ("Full name", "url", "full_name"),
    ("Email", "tel", "email"),
    ("Email", "url", "email"),
    ("Phone", "email", "phone"),
    ("Phone", "url", "phone"),
    ("LinkedIn", "email", "linkedin"),
    ("LinkedIn", "tel", "linkedin"),
    ("GitHub", "email", "github"),
    ("GitHub", "tel", "github"),
])
def test_mismatched_native_contact_control_requires_review(question, kind, key):
    result = classify_field(
        {"question": question, "label": question, "type": kind, "ambiguous": False},
        {key},
    )
    assert result == {
        "status": "human_review",
        "reason": "mismatched_contact_control",
    }


@pytest.mark.parametrize("question,kind,key", [
    ("Full name", "text", "full_name"),
    ("Email", "email", "email"),
    ("Phone", "tel", "phone"),
    ("LinkedIn", "url", "linkedin"),
    ("GitHub", "url", "github"),
])
def test_native_contact_control_mapping_preserved(question, kind, key):
    result = classify_field(
        {"question": question, "label": question, "type": kind, "ambiguous": False},
        {key},
    )
    assert result == {"status": "verified_candidate", "profile_key": key}


@pytest.mark.parametrize("question,key", [
    ("Full name", "full_name"),
    ("Email", "email"),
    ("Phone", "phone"),
    ("LinkedIn", "linkedin"),
    ("GitHub", "github"),
])
def test_generic_text_contact_control_remains_candidate(question, key):
    result = classify_field(
        {"question": question, "label": question, "type": "text", "ambiguous": False},
        {key},
    )
    assert result == {"status": "verified_candidate", "profile_key": key}


@pytest.mark.parametrize("question,kind,key", [
    ("Full name", "text", "full_name"),
    ("Email", "email", "email"),
    ("Phone", "tel", "phone"),
    ("LinkedIn", "url", "linkedin"),
    ("GitHub", "url", "github"),
])
def test_compatible_control_without_verified_fact_requires_review(question, kind, key):
    result = classify_field(
        {"question": question, "label": question, "type": kind, "ambiguous": False},
        set(),
    )
    assert result == {
        "status": "human_review",
        "reason": "unverified_profile_fact",
    }


@pytest.mark.parametrize("question,kind,key", [
    ("Full name", "text", "full_name"),
    ("Email", "email", "email"),
    ("Phone", "tel", "phone"),
    ("LinkedIn", "url", "linkedin"),
    ("GitHub", "url", "github"),
])
def test_ambiguous_compatible_control_requires_review(question, kind, key):
    result = classify_field(
        {"question": question, "label": question, "type": kind, "ambiguous": True},
        {key},
    )
    assert result == {
        "status": "human_review",
        "reason": "ambiguous_question",
    }


def test_mixed_contact_fields_preserve_order_and_review_decisions():
    fields = [
        {"question": "Email", "label": "Email", "type": "tel", "ambiguous": False},
        {"question": "Email", "label": "Email", "type": "email", "ambiguous": False},
        {"question": "Phone", "label": "Phone", "type": "tel", "ambiguous": False},
        {"question": "Referee email", "label": "Referee email", "type": "email", "ambiguous": False},
        {"question": "Full name", "label": "Full name", "type": "text", "ambiguous": False},
    ]
    results = triage_fields(fields, {"email", "full_name"})
    assert results == [
        {"status": "human_review", "reason": "mismatched_contact_control"},
        {"status": "verified_candidate", "profile_key": "email"},
        {"status": "human_review", "reason": "unverified_profile_fact"},
        {"status": "human_review", "reason": "unknown_question"},
        {"status": "verified_candidate", "profile_key": "full_name"},
    ]


def test_conflicting_contact_label_requires_review():
    result = classify_field(
        {"question": "Email", "label": "Phone", "type": "email", "ambiguous": False},
        {"email", "phone"},
    )
    assert result == {"status": "human_review", "reason": "unknown_question"}


def test_unsupported_control_remains_nontrivial():
    result = classify_field(
        {"question": "Email", "label": "Email", "type": "select-one", "ambiguous": False},
        {"email"},
    )
    assert result == {"status": "human_review", "reason": "nontrivial_control"}
'''

updated = original.replace(old, new, 1)
compile(updated, str(source_path), 'exec')
compile(regressions, str(regression_path), 'exec')

source_path.write_text(updated, encoding='utf-8')
regression_path.write_text(regressions, encoding='utf-8')

if hashlib.sha256(immutable_path.read_bytes()).hexdigest() != expected_hash:
    raise RuntimeError('Immutable regression baseline changed')
